#include <iostream>
using namespace std;
int main() {
    int a = 7, b = 2;
    double r1 = a / b;
    double r2 = (double)a / b;
    int t = -7.9;
    unsigned char u = 300;
    cout << r1 << " " << r2 << " " << t << " " << (int)u << "\n";
    cout << ('A' + b) << " " << char('A' + b) << "\n";
    cout << (-1 < 1u) << "\n";
    return 0;
}

#include <iostream>
using namespace std;
class Meter {
    double m;
public:
    Meter(double v) : m(v) { cout << "ctor(" << v << ") "; }
    ~Meter() { cout << "dtor(" << m << ") "; }
    operator double() const { cout << "op "; return m; }
};
int main() {
    Meter x = 2.5;
    x = 4;
    double sum = x + 1.5;
    cout << "sum=" << sum << "\n";
}

